Contents of file sample-app/src/payments.js:

1 | import { FEE_RATE } from './config.js';
2 | import { chargeTotal } from './invoice.js';
3 | 
4 | export class PaymentService {
5 |   constructor(ledger) {
6 |     this.ledger = ledger;
7 |     this.payments = new Map();
8 |   }
9 | 
10 |   charge({ paymentId, customer, merchant, items, idempotencyKey }) {
11 |     const amount = chargeTotal(items);
12 |     const fee = amount * FEE_RATE;
13 | 
14 |     this.ledger.post({ ref: paymentId, from: customer, to: 'clearing', amount, memo: 'charge' });
15 |     this.ledger.post({ ref: paymentId, from: 'clearing', to: 'platform_fees', amount: fee, memo: 'processing fee' });
16 | 
17 |     this.payments.set(paymentId, { paymentId, customer, merchant, amount, fee, idempotencyKey, refunded: 0, settled: false });
18 |     return { paymentId, amount, fee };
19 |   }
20 | 
21 |   settle(paymentId) {
22 |     const p = this.payments.get(paymentId);
23 |     if (!p) throw new Error(`Unknown payment ${paymentId}`);
24 | 
25 |     const fee = p.amount * FEE_RATE;
26 |     this.ledger.post({ ref: paymentId, from: 'clearing', to: 'platform_fees', amount: fee, memo: 'settlement fee' });
27 |     this.ledger.post({ ref: paymentId, from: 'clearing', to: p.merchant, amount: p.amount - fee, memo: 'merchant payout' });
28 |     p.settled = true;
29 |   }
30 | 
31 |   refund(paymentId, amount) {
32 |     const p = this.payments.get(paymentId);
33 |     if (!p) throw new Error(`Unknown payment ${paymentId}`);
34 | 
35 |     p.refunded += amount;
36 |     this.ledger.post({ ref: paymentId, from: p.merchant, to: p.customer, amount, memo: 'refund' });
37 |   }
38 | }
39 |

