2 |   constructor() {
3 |     this.entries = [];
4 |   }
5 | 
6 |   post({ ref, from, to, amount, memo = '' }) {
7 |     this.entries.push({ ref, from, to, amount, memo, seq: this.entries.length + 1 });
8 |   }
9 | 
10 |   balance(account) {
11 |     let total = 0;
12 |     for (const e of this.entries) {
13 |       if (e.to === account) total += e.amount;
14 |       if (e.from === account) total -= e.amount;
15 |     }
16 |     return total;
17 |   }
18 | 
19 |   accounts() {
20 |     return [...new Set(this.entries.flatMap((e) => [e.from, e.to]))];
21 |   }
