Contents of file sample-app/scripts/simulate-day.js:

1 | import { Ledger } from '../src/ledger.js';
2 | import { PaymentService } from '../src/payments.js';
3 | 
4 | let seed = 42;
5 | const rand = () => {
6 |   seed = (seed * 1664525 + 1013904223) % 4294967296;
7 |   return seed / 4294967296;
8 | };
9 | const pick = (arr) => arr[Math.floor(rand() * arr.length)];
10 | 
11 | const PRICES = [150, 499.99, 1250.5, 2999.99, 7500, 18999.95, 45000, 129999.99];
12 | const CUSTOMERS = Array.from({ length: 40 }, (_, i) => `customer_${i + 1}`);
13 | const MERCHANTS = ['merchant_ada_foods', 'merchant_eko_gadgets', 'merchant_jos_textiles'];
14 | const ORDERS = 500;
15 | 
16 | const ledger = new Ledger();
17 | const svc = new PaymentService(ledger);
18 | const toKobo = (naira) => Math.round(naira * 100);
19 | 
20 | // Finance team's expectation, computed in whole kobo from docs/fee-schedule.md
21 | const expected = { customers: 0, merchants: 0, fees: 0 };
22 | let retries = 0;
23 | let refundRequests = 0;
24 | 
25 | for (let n = 1; n <= ORDERS; n++) {
26 |   const paymentId = `pay_${String(n).padStart(4, '0')}`;
27 |   const items = Array.from({ length: 1 + Math.floor(rand() * 3) }, () => ({
28 |     unitPrice: pick(PRICES),
29 |     qty: 1 + Math.floor(rand() * 4),
30 |   }));
31 |   const order = { paymentId, customer: pick(CUSTOMERS), merchant: pick(MERCHANTS), items, idempotencyKey: `idem_${paymentId}` };
32 | 
33 |   const subtotalKobo = items.reduce((s, i) => s + toKobo(i.unitPrice) * i.qty, 0);
34 |   const receiptKobo = Math.round((subtotalKobo * 1075) / 1000);
35 |   const feeKobo = Math.min(Math.round((receiptKobo * 15) / 1000), 200000);
36 | 
37 |   svc.charge(order);
38 |   if (rand() < 0.03) {
39 |     svc.charge(order);
40 |     retries++;
41 |   }
42 |   svc.settle(paymentId);
43 | 
44 |   let refundedKobo = 0;
45 |   if (rand() < 0.06) {
46 |     const requests = rand() < 0.35 ? 2 : 1;
47 |     for (let r = 0; r < requests; r++) {
48 |       const requestKobo = Math.round(receiptKobo * 0.6);
49 |       svc.refund(paymentId, requestKobo / 100);
50 |       refundedKobo += Math.min(requestKobo, receiptKobo - refundedKobo);
51 |       refundRequests++;
52 |     }
53 |   }
54 | 
55 |   expected.customers += receiptKobo - refundedKobo;
56 |   expected.merchants += receiptKobo - feeKobo - refundedKobo;
57 |   expected.fees += feeKobo;
58 | }
59 | 
60 | const sum = (accounts) =>
61 |   typeof ledger.balanceKobo === 'function'
62 |     ? accounts.reduce((s, a) => s + ledger.balanceKobo(a), 0) / 100
63 |     : accounts.reduce((s, a) => s + ledger.balance(a), 0);
64 | const actual = {
65 |   customers: -sum(CUSTOMERS),
66 |   merchants: sum(MERCHANTS),
67 |   fees: ledger.balance('platform_fees'),
68 |   clearing: ledger.balance('clearing'),
69 | };
70 | 
71 | const rows = [
72 |   ['Customers paid (net)', expected.customers / 100, actual.customers],
73 |   ['Merchants received (net)', expected.merchants / 100, actual.merchants],
74 |   ['Platform fees', expected.fees / 100, actual.fees],
75 |   ['Clearing account', 0, actual.clearing],
76 | ];
77 | 
78 | console.log('\nShopLedger end of day reconciliation');
79 | console.log(`Orders: ${ORDERS} | Client retries: ${retries} | Refund requests: ${refundRequests}\n`);
80 | console.log('Account'.padEnd(28) + 'Expected (NGN)'.padEnd(20) + 'Ledger says (NGN)'.padEnd(28) + 'Difference');
81 | console.log('-'.repeat(90));
82 | 
83 | let gap = 0;
84 | for (const [name, exp, act] of rows) {
85 |   const diff = act - exp;
86 |   gap += Math.abs(diff);
87 |   console.log(name.padEnd(28) + exp.toFixed(2).padEnd(20) + String(act).padEnd(28) + diff.toFixed(2));
88 | }
89 | 
90 | console.log('-'.repeat(90));
91 | console.log(gap < 0.005 ? 'Books balance.' : `Books are off. Total discrepancy: NGN ${gap.toFixed(2)}`);
