/**
 * penny-decompose.js
 *
 * Replays the identical simulated day (seed=42, 500 orders) and measures the
 * naira impact of each finding on every account.
 *
 * Findings measured:
 *   P2  Rounding drift   – chargeTotal vs receiptTotal difference per order
 *   P3  Missing idempotency – retry doubles the customer charge AND strands
 *                             money in clearing
 *   P4  Double fees      – charge-time fee posting (should only happen at settle)
 *   P5  Missing cap      – settle-time fee in excess of the ₦2,000 cap
 *   P6  Over refund      – refund amount paid beyond the charged amount
 *   P1  Float noise      – residual after all the above is attributed
 *
 * For each order we record every component in naira (positive = account gains,
 * negative = account loses).  At the end we print per-finding column totals and
 * verify they reconcile to the simulate-day.js differences.
 */

import { receiptTotal, chargeTotal } from '../src/invoice.js';

// ── identical PRNG / data from simulate-day.js ──────────────────────────────
let seed = 42;
const rand = () => {
  seed = (seed * 1664525 + 1013904223) % 4294967296;
  return seed / 4294967296;
};
const pick = (arr) => arr[Math.floor(rand() * arr.length)];

const PRICES    = [150, 499.99, 1250.5, 2999.99, 7500, 18999.95, 45000, 129999.99];
const CUSTOMERS = Array.from({ length: 40 }, (_, i) => `customer_${i + 1}`);
const MERCHANTS = ['merchant_ada_foods', 'merchant_eko_gadgets', 'merchant_jos_textiles'];
const ORDERS    = 500;
const FEE_RATE  = 0.015;
const FEE_CAP   = 2000; // naira

const toKobo  = (naira) => Math.round(naira * 100);
const toNaira = (kobo)  => kobo / 100;

// ── accumulators (naira) ─────────────────────────────────────────────────────
// sign convention: positive = that account's balance increases due to this bug
const impact = {
  customers:    { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
  merchants:    { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
  platform_fees:{ P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
  clearing:     { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
};

// ── known simulation totals from simulate-day.js (used for reconciliation) ──
// These are the "Difference" column values (actual − expected):
//   customers:     +1300600.14
//   merchants:      -880909.92
//   platform_fees: +1799877.70
//   clearing:       +381632.35
// We will recompute them from scratch and verify.

let totalExpCustomers     = 0;
let totalExpMerchants     = 0;
let totalExpFees          = 0;

// Running actuals we compute analytically (no live Ledger needed)
let totalActCustomers     = 0;
let totalActMerchants     = 0;
let totalActFees          = 0;
let totalActClearing      = 0;

for (let n = 1; n <= ORDERS; n++) {
  // ── build order (identical to simulate-day.js) ───────────────────────────
  const paymentId = `pay_${String(n).padStart(4, '0')}`;
  const items = Array.from({ length: 1 + Math.floor(rand() * 3) }, () => ({
    unitPrice: pick(PRICES),
    qty: 1 + Math.floor(rand() * 4),
  }));
  const order = { paymentId, customer: pick(CUSTOMERS), merchant: pick(MERCHANTS), items };

  const subtotalKobo  = items.reduce((s, i) => s + toKobo(i.unitPrice) * i.qty, 0);
  const receiptKobo   = Math.round((subtotalKobo * 1075) / 1000);  // spec: once on subtotal
  const receiptNaira  = toNaira(receiptKobo);
  const feeKobo       = Math.min(Math.round((receiptKobo * 15) / 1000), 200000); // spec: capped
  const feeNairaCap   = toNaira(feeKobo);

  const chargeNaira   = chargeTotal(items);  // what code actually charges
  const isRetry       = rand() < 0.03;       // consume same rand call as simulate-day.js
  if (isRetry) rand(); // simulate-day.js calls rand() again inside charge() for retry — but
  // actually no: simulate-day.js just calls svc.charge(order) again; rand() is not called
  // inside charge() itself. The rand() < 0.03 check IS the extra rand() call. No extra needed.

  // ── refunds (consume rand() calls matching simulate-day.js) ─────────────
  let actualRefundNaira   = 0;
  let expectedRefundNaira = 0;
  let refundedKoboSoFar   = 0;

  const doRefund = rand() < 0.06;
  if (doRefund) {
    const requests       = rand() < 0.35 ? 2 : 1;
    const requestKobo    = Math.round(receiptKobo * 0.6); // same each request

    for (let r = 0; r < requests; r++) {
      // what the service actually posts (no cap check in code)
      actualRefundNaira += requestKobo / 100;
      // what the simulation script counts as expected (capped)
      const cappedKobo   = Math.min(requestKobo, receiptKobo - refundedKoboSoFar);
      expectedRefundNaira += toNaira(cappedKobo);
      refundedKoboSoFar  += cappedKobo;
    }
  }

  // ── expected (per fee schedule) ──────────────────────────────────────────
  const expCustNet  = receiptNaira - expectedRefundNaira;      // net outflow from customer
  const expMerchNet = receiptNaira - feeNairaCap - expectedRefundNaira; // net inflow to merchant
  const expFee      = feeNairaCap;

  totalExpCustomers += expCustNet;
  totalExpMerchants += expMerchNet;
  totalExpFees      += expFee;

  // ── actual (per code logic) ──────────────────────────────────────────────
  //
  // charge() postings (runs once or twice):
  //   customer → clearing : chargeNaira        (×1 or ×2 if retry)
  //   clearing → platform_fees : chargeNaira×0.015  (×1 or ×2 if retry)
  //
  // settle() postings (always once):
  //   p.amount = chargeNaira (retry overwrites with identical value)
  //   clearing → platform_fees : chargeNaira×0.015
  //   clearing → merchant      : chargeNaira×0.985
  //
  // refund() postings (0, 1 or 2 times):
  //   merchant → customer : requestKobo/100  (no cap)

  const feeCharge  = chargeNaira * FEE_RATE;  // per charge() call
  const feeSettle  = chargeNaira * FEE_RATE;  // settle() recomputes same way
  const chargeRuns = isRetry ? 2 : 1;

  // account actuals for this order
  const actCustDebit  = chargeNaira * chargeRuns;           // customer debited
  const actCustCredit = actualRefundNaira;                  // customer refunded
  const actCustNet    = actCustDebit - actCustCredit;       // net outflow

  const actMerchCredit = chargeNaira * 0.985;               // payout (settle)
  const actMerchDebit  = actualRefundNaira;                 // refunds merchant pays
  const actMerchNet    = actMerchCredit - actMerchDebit;    // net inflow

  const actFees = feeCharge * chargeRuns + feeSettle;       // all fee postings

  // clearing: sum of all postings in/out
  const actClearing =
      chargeNaira * chargeRuns     // customer → clearing (in)
    - feeCharge   * chargeRuns     // clearing → platform_fees (out, each charge call)
    - feeSettle                    // clearing → platform_fees (out, settle)
    - chargeNaira * 0.985;         // clearing → merchant (out, settle payout)
  // = chargeNaira*chargeRuns - feeCharge*chargeRuns - feeSettle - chargeNaira*0.985

  totalActCustomers += actCustNet;
  totalActMerchants += actMerchNet;
  totalActFees      += actFees;
  totalActClearing  += actClearing;

  // ── attribute differences to findings ────────────────────────────────────
  //
  // P2 – rounding drift: chargeNaira vs receiptNaira
  //   Customers: charged chargeNaira instead of receiptNaira (per charge call)
  //   The drift itself (chargeNaira - receiptNaira) flows into/out of clearing
  //   and ultimately affects payout. Attribution:
  //     customers:     +drift per charge call (overcharged)
  //     clearing:      +drift per charge call (extra in from customer),
  //                    −drift×0.015 (extra fee from clearing), −drift×0.985 (extra payout)
  //                    net clearing from drift = drift − drift×0.015 − drift×0.985 = 0
  //     platform_fees: +drift×0.015 per charge call (and settle)
  //     merchants:     +drift×0.985 (payout based on chargeNaira not receiptNaira)
  //   Simplification: measure as (chargeNaira - receiptNaira) per charge call.
  const drift = chargeNaira - receiptNaira; // can be + or −
  impact.customers.P2     += drift * chargeRuns;             // extra outflow
  impact.merchants.P2     += drift * 0.985;                  // settle payout uses chargeNaira
  impact.platform_fees.P2 += drift * FEE_RATE * chargeRuns  // charge-time fees on drift
                           +  drift * FEE_RATE;              // settle-time fee on drift
  // clearing nets to 0 from drift (it passes through)
  impact.clearing.P2      += 0;

  // P3 – missing idempotency: retry charges customer a second time
  //   The retry posts:  customer→clearing: chargeNaira  and  clearing→platform_fees: feeCharge
  //   But settle() only runs once (using the overwritten p.amount = chargeNaira).
  //   So the retry chargeNaira credit to clearing is never fully paid out.
  //   Customer: extra chargeNaira debit
  //   clearing: +chargeNaira (retry in) −feeCharge (retry fee out) but no extra settle payout
  //             = chargeNaira×(1−0.015) = chargeNaira×0.985 stranded
  //   platform_fees: +feeCharge (retry charge-time fee)
  //   merchant: unchanged (settle runs once, payout unchanged)
  if (isRetry) {
    impact.customers.P3      -= chargeNaira;        // extra debit (worse for customer → negative)
    impact.platform_fees.P3  += feeCharge;          // extra fee from retry charge
    impact.clearing.P3       += chargeNaira * 0.985; // stranded retry credit minus fee paid out
    impact.merchants.P3      += 0;                  // settle payout unaffected
  }

  // P4 – double fees: the charge-time fee posting should not exist
  //   charge() posts clearing→platform_fees: feeCharge (chargeRuns times)
  //   That entire amount should be zero (fee should only be taken at settle).
  //   Affected:
  //     platform_fees: +feeCharge per charge call (illegitimate extra income)
  //     clearing:      −feeCharge per charge call (incorrectly drained)
  //   Merchant payout and customer debit are unaffected by this posting directly.
  //   (Merchant payout = chargeNaira − feeSettle; feeSettle still runs at settle.)
  impact.platform_fees.P4 += feeCharge * chargeRuns;
  impact.clearing.P4      -= feeCharge * chargeRuns;
  impact.customers.P4     += 0;
  impact.merchants.P4     += 0;

  // P5 – missing fee cap: settle fee uses chargeNaira×0.015 instead of min(...,2000)
  //   The excess is (feeSettle − feeNairaCap) where feeSettle = chargeNaira×0.015.
  //   This excess is deducted from clearing and paid to platform_fees,
  //   which reduces the merchant payout (payout = chargeNaira − feeSettle).
  //   On orders where chargeNaira×0.015 ≤ feeNairaCap, excessFee = 0.
  const feeSettleUncapped = chargeNaira * FEE_RATE;
  const excessFee = Math.max(0, feeSettleUncapped - feeNairaCap);
  impact.platform_fees.P5 += excessFee;
  impact.merchants.P5     -= excessFee;   // merchant payout is chargeNaira−feeSettle; excess reduces it
  impact.clearing.P5      += 0;           // clearing still nets zero from the settle pair (fee+payout = chargeNaira)
  impact.customers.P5     += 0;

  // P6 – over refund: actual refund may exceed expected refund
  //   Extra refund = actualRefundNaira − expectedRefundNaira (≥ 0)
  //   This extra is paid merchant→customer, so:
  //     customer:  gains extra (negative net outflow → reduces actCustNet vs expCustNet)
  //     merchant:  pays extra (reduces merchant net inflow)
  const extraRefund = actualRefundNaira - expectedRefundNaira;
  impact.customers.P6     -= extraRefund;  // customer receives more back → net outflow decreases
  impact.merchants.P6     -= extraRefund;  // merchant pays more out
  impact.platform_fees.P6 += 0;
  impact.clearing.P6      += 0;
}

// ── sum impacts per account ──────────────────────────────────────────────────
const accounts = ['customers', 'merchants', 'platform_fees', 'clearing'];
const findings = ['P2', 'P3', 'P4', 'P5', 'P6'];

// ── compute float noise (P1) = residual ─────────────────────────────────────
// The differences from simulate-day.js (actual − expected):
const simDiff = {
  customers:     totalActCustomers  - totalExpCustomers,
  merchants:     totalActMerchants  - totalExpMerchants,
  platform_fees: totalActFees       - totalExpFees,
  clearing:      totalActClearing   - 0,  // expected clearing = 0
};

const attributedDiff = {};
for (const acc of accounts) {
  attributedDiff[acc] = findings.reduce((s, f) => s + impact[acc][f], 0);
}

const noise = {};
for (const acc of accounts) {
  noise[acc] = simDiff[acc] - attributedDiff[acc];
}

// ── output ───────────────────────────────────────────────────────────────────
const r = (n) => Number(n.toFixed(2));

console.log('\nShopLedger Penny Decomposition');
console.log('Identifies naira impact of each finding on each account\n');

// Header
const cols = [...findings, 'P1-noise', 'TOTAL', 'sim-diff', 'check'];
const colW = 14;
console.log('Account'.padEnd(18) + cols.map(c => c.padStart(colW)).join(''));
console.log('-'.repeat(18 + cols.length * colW));

for (const acc of accounts) {
  const label = acc === 'platform_fees' ? 'Platform fees' :
                acc.charAt(0).toUpperCase() + acc.slice(1);

  const vals = findings.map(f => r(impact[acc][f]));
  const pnoise = r(noise[acc]);
  const total  = r(vals.reduce((s, v) => s + v, 0) + pnoise);
  const sd     = r(simDiff[acc]);
  const check  = r(total - sd); // should be ~0

  const row = [...vals, pnoise, total, sd, check];
  console.log(label.padEnd(18) + row.map(v => String(v).padStart(colW)).join(''));
}

console.log('-'.repeat(18 + cols.length * colW));
console.log('\nPositive = account gains money. Negative = account loses money.');
console.log('P1-noise = float accumulation residual after all named bugs are attributed.');
console.log('"check" column should be 0.00 for every row (decomposition is complete).\n');

// ── per-finding totals ────────────────────────────────────────────────────────
console.log('Per-finding cross-account summary (naira impact):');
console.log('Finding'.padEnd(10) + ['Customers','Merchants','Fees','Clearing','Net zero?'].map(c => c.padStart(14)).join(''));
console.log('-'.repeat(10 + 5 * 14));
for (const f of [...findings, 'P1']) {
  const cu  = f === 'P1' ? r(noise.customers)     : r(impact.customers[f]);
  const me  = f === 'P1' ? r(noise.merchants)     : r(impact.merchants[f]);
  const fe  = f === 'P1' ? r(noise.platform_fees) : r(impact.platform_fees[f]);
  const cl  = f === 'P1' ? r(noise.clearing)      : r(impact.clearing[f]);
  const net = r(cu + me + fe + cl);
  const ok  = Math.abs(net) < 0.02 ? 'yes' : 'NO';
  console.log(f.padEnd(10) + [cu, me, fe, cl, `${net} (${ok})`].map(v => String(v).padStart(14)).join(''));
}
console.log('');

/**
 * penny-decompose.js
 *
 * Replays the identical simulated day (seed=42, 500 orders) and measures the
 * naira impact of each finding on every account.
 *
 * Findings measured:
 *   P2  Rounding drift   – chargeTotal vs receiptTotal difference per order
 *   P3  Missing idempotency – retry doubles the customer charge AND strands
 *                             money in clearing
 *   P4  Double fees      – charge-time fee posting (should only happen at settle)
 *   P5  Missing cap      – settle-time fee in excess of the ₦2,000 cap
 *   P6  Over refund      – refund amount paid beyond the charged amount
 *   P1  Float noise      – residual after all the above is attributed
 *
 * For each order we record every component in naira (positive = account gains,
 * negative = account loses).  At the end we print per-finding column totals and
 * verify they reconcile to the simulate-day.js differences.
 */

import { receiptTotal, chargeTotal } from '../src/invoice.js';

// ── identical PRNG / data from simulate-day.js ──────────────────────────────
let seed = 42;
const rand = () => {
  seed = (seed * 1664525 + 1013904223) % 4294967296;
  return seed / 4294967296;
};
