  impact.customers.P4     += 0;
  impact.merchants.P4     += 0;

  // P5 – missing fee cap: settle fee uses chargeNaira×0.015 instead of min(...,2000)
  //   The excess is (feeSettle − feeNairaCap) where feeSettle = chargeNaira×0.015.
  //   This excess is deducted from clearing and paid to platform_fees,
  //   which reduces the merchant payout (payout = chargeNaira − feeSettle).
  //   On orders where chargeNaira×0.015 ≤ feeNairaCap, excessFee = 0.
  const feeSettleUncapped = chargeNaira * FEE_RATE;
  const excessFee = Math.max(0, feeSettleUncapped - feeNairaCap);
  impact.platform_fees.P5 += excessFee;
  impact.merchants.P5     -= excessFee;   // merchant payout is chargeNaira−feeSettle; excess reduces it
  impact.clearing.P5      += 0;           // clearing still nets zero from the settle pair (fee+payout = chargeNaira)
  impact.customers.P5     += 0;

