+    impact.platform_fees.P3  += feeCharge;          // extra fee from retry charge
+    impact.clearing.P3       += chargeNaira * 0.985; // stranded retry credit minus fee paid out
+    impact.merchants.P3      += 0;                  // settle payout unaffected
+  }
+
+  // P4 – double fees: the charge-time fee posting should not exist
+  //   charge() posts clearing→platform_fees: feeCharge (chargeRuns times)
+  //   That entire amount should be zero (fee should only be taken at settle).
+  //   Affected:
+  //     platform_fees: +feeCharge per charge call (illegitimate extra income)
+  //     clearing:      −feeCharge per charge call (incorrectly drained)
