/**
 * P1 — Float money
 * Rule 1: All money is stored and calculated in whole kobo. No fractional kobo.
 *
 * The test drives a charge+settle cycle with a price that produces a
 * non-integer kobo value under the current code (₦999.99 × 1.075 × 0.015
 * = ₦16.12484… = 1612.484… kobo — fractional). It then asserts that every
 * ledger entry's amount is a whole number of kobo, and that every account
 * balance returned by the ledger is a whole number of kobo.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Ledger } from '../../src/ledger.js';
import { PaymentService } from '../../src/payments.js';

const isWholeKobo = (n) => Number.isInteger(Math.round(n * 100)) && Math.round(n * 100) === n * 100;

test('P1: all ledger entry amounts are whole kobo (no fractional kobo)', () => {
  const ledger = new Ledger();
  const svc = new PaymentService(ledger);

  // ₦999.99 × 1 item → chargeTotal = round2(999.99 × 1.075) = round2(1074.98925) = 1074.99 naira
  // fee = 1074.99 × 0.015 = 16.12485 naira = 1612.485 kobo  ← fractional kobo
  const order = {
    paymentId: 'pay_p1',
    customer: 'cust_1',
    merchant: 'merch_1',
    items: [{ unitPrice: 999.99, qty: 1 }],
    idempotencyKey: 'idem_p1',
  };

  svc.charge(order);
  svc.settle('pay_p1');

  for (const entry of ledger.entries) {
    const kobo = entry.amount * 100;
    assert.ok(
      Number.isInteger(Math.round(kobo)) && Math.abs(kobo - Math.round(kobo)) < 1e-9,
      `Entry "${entry.memo}" amount ${entry.amount} naira = ${kobo} kobo — not a whole number of kobo`
    );
  }
});

test('P1: ledger balance() returns a whole number of kobo', () => {
  const ledger = new Ledger();
  const svc = new PaymentService(ledger);

  const order = {
    paymentId: 'pay_p1b',
    customer: 'cust_1',
    merchant: 'merch_1',
    items: [{ unitPrice: 999.99, qty: 1 }],
    idempotencyKey: 'idem_p1b',
  };

  svc.charge(order);
  svc.settle('pay_p1b');

  for (const account of ledger.accounts()) {
    const bal = ledger.balance(account);
    const kobo = bal * 100;
    assert.ok(
      Math.abs(kobo - Math.round(kobo)) < 1e-9,
      `Account "${account}" balance ${bal} naira = ${kobo} kobo — not a whole number of kobo`
    );
  }
});

