    paymentId: 'pay_p1c',
    customer: 'cust_1',
    merchant: 'merch_1',
    items: [{ unitPrice: 1000, qty: 2 }], // 2000 naira → VAT 7.5% = 2150 naira
    idempotencyKey: 'idem_p1c',
